using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Windows;
using NAudio.Wave;
using NAudio.Wave.SampleProviders;

namespace AquilaLocal;

public enum UiSound
{
	None,
	Send,
	Reply,
	Ready,
	Stop,
	Notice,
	Copy,
	Attach,
	Delete
}

/// <summary>
/// Quiet interface sounds. Eight short sine-based WAVs (generated by tools/make_sounds.py) are
/// mixed into one output that opens on the first sound and closes after 15 seconds of silence,
/// so the audio device is not held. Never used for streamed tokens, hover, typing or scrolling.
/// </summary>
public static class UiSounds
{
	private sealed class Clip : ISampleProvider
	{
		private readonly float[] samples;

		private readonly float gain;

		private int position;

		public WaveFormat WaveFormat { get; }

		public Clip(float[] samples, float gain, WaveFormat format)
		{
			this.samples = samples;
			this.gain = gain;
			WaveFormat = format;
		}

		public int Read(float[] buffer, int offset, int count)
		{
			int num = Math.Min(count, samples.Length - position);
			for (int i = 0; i < num; i++)
			{
				buffer[offset + i] = samples[position + i] * gain;
			}
			position += num;
			return num;
		}
	}

	private static readonly object Gate = new object();

	private static readonly WaveFormat Format = WaveFormat.CreateIeeeFloatWaveFormat(44100, 1);

	private static readonly Dictionary<UiSound, float[]> Clips = new Dictionary<UiSound, float[]>();

	private static readonly Dictionary<UiSound, DateTime> LastPlayed = new Dictionary<UiSound, DateTime>();

	private static WaveOutEvent? output;

	private static MixingSampleProvider? mixer;

	private static Timer? idle;

	private static bool loaded;

	private static UiSound pending;

	private static DateTime pendingAt;

	public static bool Enabled { get; set; } = true;

	/// <summary>Master volume, 0 to 1.</summary>
	public static double Volume { get; set; } = 0.5;

	/// <summary>While this returns true (the voice is speaking) only Notice plays.</summary>
	public static Func<bool>? IsSpeaking { get; set; }

	private static int Priority(UiSound sound)
	{
		return sound switch
		{
			UiSound.Notice => 3,
			UiSound.Ready => 2,
			UiSound.Reply => 1,
			_ => 0,
		};
	}

	public static void Play(UiSound sound)
	{
		if (sound == UiSound.None || !Enabled || Volume <= 0.001)
		{
			return;
		}
		try
		{
			if (sound != UiSound.Notice && (IsSpeaking?.Invoke() ?? false))
			{
				return;
			}
			lock (Gate)
			{
				DateTime utcNow = DateTime.UtcNow;
				if (LastPlayed.TryGetValue(sound, out var value) && (utcNow - value).TotalMilliseconds < 150.0)
				{
					return;
				}
				// Two requests within 60 ms: keep only the more important one.
				if (pending != UiSound.None && (utcNow - pendingAt).TotalMilliseconds < 60.0 && Priority(pending) > Priority(sound))
				{
					return;
				}
				pending = sound;
				pendingAt = utcNow;
				LastPlayed[sound] = utcNow;
				Load();
				if (!Clips.TryGetValue(sound, out float[] value2))
				{
					return;
				}
				EnsureOutput();
				mixer?.AddMixerInput(new Clip(value2, (float)Math.Clamp(Volume, 0.0, 1.0), Format));
				idle?.Change(15000, Timeout.Infinite);
			}
		}
		catch (Exception)
		{
			// No audio device, or the device went away: sounds are optional.
		}
	}

	private static void EnsureOutput()
	{
		if (output != null)
		{
			return;
		}
		mixer = new MixingSampleProvider(Format)
		{
			ReadFully = true
		};
		output = new WaveOutEvent
		{
			DesiredLatency = 80
		};
		output.Init(mixer);
		output.Play();
		idle = new Timer(delegate
		{
			Close();
		}, null, 15000, Timeout.Infinite);
	}

	private static void Close()
	{
		lock (Gate)
		{
			try
			{
				output?.Stop();
				output?.Dispose();
			}
			catch (Exception)
			{
			}
			output = null;
			mixer = null;
			idle?.Dispose();
			idle = null;
		}
	}

	private static void Load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;
		foreach (UiSound value in Enum.GetValues(typeof(UiSound)))
		{
			if (value == UiSound.None)
			{
				continue;
			}
			try
			{
				Uri uriResource = new Uri("pack://application:,,,/Sounds/" + value.ToString().ToLowerInvariant() + ".wav");
				using Stream stream = Application.GetResourceStream(uriResource).Stream;
				using WaveFileReader waveFileReader = new WaveFileReader(stream);
				byte[] array = new byte[waveFileReader.Length];
				int num = waveFileReader.Read(array, 0, array.Length);
				float[] array2 = new float[num / 2];
				for (int i = 0; i < array2.Length; i++)
				{
					array2[i] = (float)BitConverter.ToInt16(array, i * 2) / 32768f;
				}
				Clips[value] = array2;
			}
			catch (Exception)
			{
			}
		}
	}
}
